<?php
function parallel14(array $arguments):array{global $tmp;$jobs=[];foreach($arguments as $args){$process=proc_open(array_merge([PHP_BINARY,'-d','ffi.enable=1',__DIR__.'/security_worker.php',$tmp.'/config.json'],$args),[1=>['pipe','w'],2=>['pipe','w']],$pipes);$jobs[]=[$process,$pipes];}$out=[];foreach($jobs as [$process,$pipes]){$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($process)!==0||$stderr!==''){throw new RuntimeException($stderr);}$out[]=trim($stdout);}return $out;}
test('eight parallel uses of one recovery code accept exactly once',static function()use($a){[$id,$s,$r]=factor14();$out=parallel14(array_fill(0,8,['factor',(string)$id,$r['codes'][0]]));same(1,count(array_filter($out,static function($v){return $v==='accepted';})));same(7,$a->secondFactor->status($id)['recovery_remaining']);});
test('eight parallel purchases compete for one coupon quota without overuse',static function()use($a){$id=product('digital','balance','10.00');$code=coupon14(['max_uses'=>1]);$args=[];for($i=0;$i<8;$i++){$u=user14();$a->wallet->adjust($u,'balance',1000,'coupon-race:'.$u,'fixture');$args[]=['coupon',(string)$u,(string)$id,$code];}$out=parallel14($args);same(1,count(array_filter($out,static function($v){return $v==='accepted';})));same(1,(int)$a->db->value('SELECT uses FROM cy_coupons WHERE code=?',[$code]));same(1,(int)$a->db->value('SELECT COUNT(*) FROM cy_orders WHERE item_id=?',[$id]));});
